public static boolean hasPathSum(BinNode<Integer> t, int sum) {
    int rest = sum - t.getValue();
    if (!t.hasLeft() && !t.hasRight()) {
        return rest == 0;
    }
    if (t.hasLeft() && hasPathSum(t.getLeft(), rest)) {
        return true;
    }
    return t.hasRight() && hasPathSum(t.getRight(), rest);
}

public static int countOneChild(BinNode<Integer> t) {
    if (t == null) {
        return 0;
    }
    int count = countOneChild(t.getLeft()) + countOneChild(t.getRight());
    if (t.hasLeft() != t.hasRight()) {
        count++;
    }
    return count;
}

